def compute(vars):
    average_revenue = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average_revenue,
        "trace": {
            "revenues": [vars["v1"], vars["v2"]],
            "count": 2,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
